  homepage "https://github.com/gstark/dev-domains"
  url "https://github.com/gstark/dev-domains/archive/refs/tags/v0.1.4.tar.gz"
  sha256 "39e1863f989363f4b4688773c618ba9f7c2f2e2ea36939f8c564517edff74c38"
